# parables, the counsel, Shittim, the yoking, the hanging and the judges, Zimri, the spear, the count, the covenant of peace, the Midian
# command), five CASE kinds for the exam's scene, sixteen effects, six registry rows (Balak, Balaam, the she-ass, the Moabites, Zimri,
# Cozbi), the 54th daemon's block, the functions block, the dependency span and edges, the installation probe's count. The `he` is the
# whole verse from the pointed DB text (cantillation stripped), the witnesses the plain consonantal verses — no anchor word typed.
# Idempotent (add_types_chukat.py's form).
import re, sqlite3, yaml
ROOT = "<repo-old>"
db = sqlite3.connect(f"file:{ROOT}/elijah_docket/tanakh.sqlite?mode=ro", uri=True)
def words(book, ch, vs):
    return [r[0] for r in db.execute("SELECT w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, vs)).fetchall()]
def PV(book, ch, vs):
    ws = words(book, ch, vs); assert ws, (book, ch, vs)
    return ' '.join(''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05AF)) for w in ws)
def LV(book, ch, vs):
    return ' '.join(''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05C7)) for w in words(book, ch, vs))
q = lambda s: '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'
N = 'Num'
def HE(ch, lo, hi, en):
    return ' · '.join(PV(N, ch, v) + ' (%s — Num %d:%d)' % (en if v == lo else 'the verse continues', ch, v) for v in range(lo, hi + 1))
def WIT(ch, lo, hi):
    return ['Num %d:%d | %s' % (ch, v, LV(N, ch, v)) for v in range(lo, hi + 1)]
